import scala.language.dynamics

class SessionFwd(target: Session) extends Dynamic:
  @volatile private var live = true
  def applyDynamic(name: String)(args: Any*): Any =
    if !live then throw new IllegalStateException("capability revoked")
    else target.getClass.getMethod(name, args.map(_.getClass)*).invoke(target, args*)
  def revoke(): Unit = live = false
